<template>
  <div class="lottery-history lottery-history">
    <appHeader :title="title" :istop="num"></appHeader>
    <ul class="tabs" v-if="logInfo?.role<3">
        <li  @click="yTab(1)" :class="ytype == 1 ? 'active' : 'default'">开奖设置</li>
        <li  @click="yTab(2)" :class="ytype == 2 ? 'active' : 'default'">历史开奖</li>
        <div class="per-adds" @click="addOpen">新增期数</div>
    </ul>
    <div class="mkopen-top">
      <div class="per-tab" @click="yxsTab">
        <div class="per-tab-t">{{lotItem.name}}</div>
        <img class="per-tab-img" src="../../assets/images/adown.webp" >
      </div>
      <div class="per-tab" @click="yxqTab">
        <div class="per-tab-t">{{yxq[param.object.status]}}</div>
        <img class="per-tab-img" src="../../assets/images/adown.webp" >
      </div>
      <div class="per-relash">刷新</div>
    </div>
    <div class="mkopen-cont1" v-if="tableData.length>0&&ytype==1">
      <van-list
				v-model="loading"          
				:finished="finished"  
				:immediate-check="false"      
				finished-text="没有更多了"  
				@load="loadMoreRecord"              
			>
        <div class="his-item" v-for="its in tableData" :key="its.period">
           <div class="his-item-top">
              <div class="his-item-name">期数</div>
              <div class="his-item-isue">{{its.period}}</div>
              <div class="his-item-time">{{its.openTime}}</div>
              <div class="his-item-week">{{getWeek(its.openTimeDay)}}</div>
           </div>
           <div class="his-open" v-if="its.maks&&its.maks.length>0">
              <div class="head-list-issue-num" v-if="its.lotteryId!=10101&&its.lotteryId!=10102">
                <div class="head-list-issue-num-t" v-for="(item,index) in its.maks.slice(0,6)" :key="index">
                  <img :src="getNumImage(item && item.num)"/>
                  <p>{{item.num=='num'?'空':item.name}}</p>
                </div>
                <div class="head-add">+</div>
                <div class="head-list-issue-num-t" v-if="its.maks[6]">
                  <img :src="getNumImage(its.maks[6].num)"/>
                  <p>{{its.maks[6].num=='num'?'空':its.maks[6].name}}</p>
                </div>
              </div>
              <div class="head-list-issue-num" v-if="its.lotteryId==10101||its.lotteryId==10102">
                <div class="head-list-issue-num-ts" v-for="(item,index) in its.maks.slice(0,7)" :key="index">
                    <img  :src="getNumImage(item && item.num)"/>
                </div>
                <span class="head-adds">+</span>
                <div class="head-list-issue-num-ts" v-if="its.maks[7]">
                    <img :src="getNumImage(its.maks[7] && its.maks[7].num)"/>
                </div>
              </div>
           </div>
           <div class="his-resut">
              <div class="his-resut-ts">
                 <div class="his-resut-cont">{{ its.betAmount?its.betAmount:'-' }}</div>
                 <div class="his-resut-cont">{{ its.portalResult?userTime.isDot(its.portalResult):'-' }}</div>
                 <div class="his-resut-cont">{{ its.companyResult?userTime.isDot(its.companyResult):'-' }}</div>
                 <div class="his-resut-cont">{{ its.companyPlc?userTime.isDot(its.companyPlc):'-' }}</div>
              </div>
              <div class="his-resut-t">
                 <div class="his-resut-btn">
                    <div class="his-resut-btns">下注金额</div>
                 </div>
                 <div class="his-resut-btn">
                    <div class="his-resut-btns">会员结果</div>
                 </div>
                 <div class="his-resut-btn">
                    <div class="his-resut-btns">公司结果</div>
                 </div>
                 <div class="his-resut-btn">
                    <div class="his-resut-btns">赔率差</div>
                 </div>
              </div>
           </div>
           <div class="his-status">
              <div class="his-status-t">{{its.status==1?'有效期数':'作废期数' }}</div>
              <div class="his-status-icon">
                <img class="bjicon" v-if="its.isOpen!=0&&its.isOpen!=5" src="@/assets/images/wbjicon.webp" />
                <img class="bjicon" v-if="its.isOpen==5" src="@/assets/images/bjicon.webp" />
                <div class="his-status-name">{{getStatus(its.isOpen)}}</div>
              </div>
              <div class="his-status-bts" @click.stop="editOpen(its)">{{its.isOpen==5?'编辑':'颁奖'}}</div>
           </div>
        </div>
      </van-list>
    </div>
    <div :class="logInfo?.role<3?'mkopen-cont1':'mkopen-cont'" v-if="tableData.length>0&&ytype==2">
      <van-list
				v-model="loading"          
				:finished="finished"  
				:immediate-check="false"      
				finished-text="没有更多了"  
				@load="loadMoreRecord"              
			>
        <div class="his-item" v-for="its in tableData" :key="its.period">
           <div class="his-item-top">
              <div class="his-item-name">期数</div>
              <div class="his-item-isue">{{its.period}}</div>
              <div class="his-item-time">{{its.openTime}}</div>
              <div class="his-item-week">{{getWeek(its.openTimeDay)}}</div>
           </div>
           <div class="his-open" v-if="its.maks&&its.maks.length>0">
              <div class="head-list-issue-num" v-if="its.lotteryId!=10101&&its.lotteryId!=10102">
                <div class="head-list-issue-num-t" v-for="(item,index) in its.maks.slice(0,6)" :key="index">
                  <img :src="getNumImage(item && item.num)"/>
                  <p>{{item.num=='num'?'空':item.name}}</p>
                </div>
                <div class="head-add">+</div>
                <div class="head-list-issue-num-t" v-if="its.maks[6]">
                  <img :src="getNumImage(its.maks[6].num)"/>
                  <p>{{its.maks[6].num=='num'?'空':its.maks[6].name}}</p>
                </div>
              </div>
              <div class="head-list-issue-num" v-if="its.lotteryId==10101||its.lotteryId==10102">
                <div class="head-list-issue-num-ts" v-for="(item,index) in its.maks.slice(0,7)" :key="index">
                    <img  :src="getNumImage(item && item.num)"/>
                </div>
                <span class="head-adds">+</span>
                <div class="head-list-issue-num-ts" v-if="its.maks[7]">
                    <img :src="getNumImage(its.maks[7] && its.maks[7].num)"/>
                </div>
              </div>
           </div>
           <div class="his-title">
              <div class="his-t">特大小</div>
              <div class="his-t">特单双</div>
              <div class="his-t">总分</div>
              <div class="his-t">总单双</div>
              <div class="his-t">总大小</div>
              <div class="his-t">合单双</div>
              <div class="his-t">合大小</div>
              <div class="his-t">色波</div>
           </div>
           <div class="his-tname">
              <div class="his-img" v-for="(bbs,ins) in  its.resultList" v-show="ins!=2">
                  <div :class="getColorClass(bbs)">{{bbs}}</div>
              </div>
           </div>
        </div>
      </van-list>
    </div>
    <!-- 选择彩种 -->
    <van-popup v-model:show="showLottery" position="bottom" class="popTop">
			<div class="pop-list">
				<div class="pop-line">
					<div class="pop-lines">
						<div class="pop-list-line"></div>
					</div>
					<div class="pop-head">
						<div class="pop-head-t">彩种选择</div>
						<div @click="yxclose" class="pop-head-img">关闭</div>
					</div>
				</div>
				<div class="pop-cont">
					<div class="flex-item">
						<div class="yx-select" @click="onConfirm(item)" :class="lotItem.id==item.id?'active':''" v-for="item in list" :key="item.id">{{item.name}}</div>
					</div> 
				</div>
			</div>
		</van-popup>
     <!-- 选择彩种 -->
    <van-popup v-model:show="yxqShow" position="bottom" class="popTop">
			<div class="pop-list">
				<div class="pop-line">
					<div class="pop-lines">
						<div class="pop-list-line"></div>
					</div>
					<div class="pop-head">
						<div class="pop-head-t">状态选择</div>
						<div @click="yxclose" class="pop-head-img">关闭</div>
					</div>
				</div>
				<div class="pop-cont">
					<div class="flex-item">
						<div class="yx-select" @click="switchType(3)" :class="param.object.status==3?'active':''">全部期数</div>
            <div class="yx-select" @click="switchType(1)" :class="param.object.status==1?'active':''">有效期数</div>
            <div class="yx-select" @click="switchType(2)" :class="param.object.status==2?'active':''">作废期数</div>
					</div> 
				</div>
			</div>
		</van-popup>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import { getLunar } from 'chinese-lunar-calendar'
import { useTimeUtils } from '@/utils/time'
import { useAppStore } from '@/store/index'
const userTime = useTimeUtils();
// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const appStore = useAppStore()

const title = ref('历史开奖')
const num = ref(3)
const dateTime = ref('')
const list = ref([])
const lotItem = ref('')
const showTime = ref(false)
const currentDate = ref(new Date())
const showLottery = ref(false)
const columns = ref([])
const ytype = ref(1)
const yxqShow = ref(false)
const param = ref({
  object: {
    lotteryId: '',
    status:1
  },
  pageNum: 0,
  pageSize: 10,
})
const pages = ref({
  pageNum: 0,
  total: 0,
})
const tableData = ref([])
const loading = ref(false)
const finished = ref(false)
const current = ref(0)
const isLoading =ref(false)
const logInfo = ref('')
const types = ref('')
const yxq = ref({
  1:'有效期数',
  2:'作废期数',
  3:'全部期数'
})
const first = ref('')
const zodiac = ref([{
    name:"鼠",
    id:1,
    sort:1
}, {
    name:"牛",
    id:2,
    sort:2
}, {
    name:"虎",
    id:3,
    sort:3
}, {
    name:"兔",
    id:4,
    sort:4
}, {
    name:"龙",
    id:5,
    sort:5
}, {
    name:"蛇",
    id:6,
    sort:6
}, {
    name:"马",
    id:7,
    sort:7
}, {
    name:"羊",
    id:8,
    sort:8
}, {
    name:"猴",
    id:9,
    sort:9
}, {
    name:"鸡",
    id:10,
    sort:10
}, {
    name:"狗",
    id:11,
    sort:11
}, {
    name:"猪",
    id:12,
    sort:12
}])
// 添加更多状态管理
const loadStatus = ref('idle'); // idle | loading | success | error | finished
// 初始化组件
onMounted(() => {
    let tts  = JSON.parse(localStorage.getItem('userInfo'));
    logInfo.value = tts;
    const uus = localStorage.getItem('auuids')
    if(tts.isInit==2&&uus){
      if(tts.role>2){
         ytype.value =2;
      }
      getLottery();
    }
})
const addOpen = () =>{
   router.push({path:`/AddOpen/${first.value}`,query:{type:types.value}})
}
const editOpen = (item) =>{
  if(item.lotteryId!=10102&&item.lotteryId!=10101){
     router.push({path:`/EditOpen/${item.id}`})
  }else{
     router.push({path:`/EddTcOpen/${item.id}`})
  }
}
const getStatus = (status) => {
    if (status == 5) {
        return '已颁奖'
    } else if (status == 0) {
        return '已封盘'
    } else {
        return '未颁奖'
    }
}
const yTab = (num) =>{
   ytype.value = num;
}
const getNumImage = (id) => {
  // 默认图片
  const defaultImg = 'num'
  
  // 安全获取数字
  let numId
  try {
    numId = parseInt(id)
  } catch (e) {
    numId = NaN
  }
  
  // 判断是否为有效数字且在1-49之间
  const isValid = !isNaN(numId) && numId > 0 && numId < 50
  
  const imgName = isValid ? numId : defaultImg
  
  try {
    return new URL(`../../assets/images/number/${imgName}.svg`, import.meta.url).href
  } catch (error) {
    console.error('图片加载失败:', imgName, error)
    return new URL(`../../assets/images/number/num.svg`, import.meta.url).href
  }
}
const yxsTab = ()=>{
   showLottery.value = true;
}
const yxqTab = () =>{
    yxqShow.value = true;
}
const yxclose = () =>{
  showLottery.value = false;
  yxqShow.value = false;
}
const getDx = (itens,num) =>{
  if(itens){
      if(itens[num]>0&&itens[num]<50){
        return  true;
      }else{
        return false;
      }
  }
}
const getCorlor = (vals) =>{
  let corle = '';
  if(vals){
    if(appStore.redlist.indexOf(parseInt(vals)) != -1){
      corle = 'background:#DB2222';
    }else if(appStore.bluelist.indexOf(parseInt(vals)) != -1){
      corle = 'background:#0D63B8';
    }else if(appStoregreenlist.indexOf(parseInt(vals)) != -1){
      corle = 'background:#11914A';
    }
  }
  return corle;
}
const getColorClass = (value) =>{
      // 转换为字符串进行比较
  const val = String(value)
  
  // 大单蓝
  if (val === '大' || val === '单' || val === '蓝') {
    return 'his-img-blue'
  }
  
  // 小双绿
  if (val === '小' || val === '双') {
    return 'his-img-orange'
  }
  
  // 红
  if (val === '红') {
    return 'his-img-red'
  }
  if (val === '绿' || val === '和') {
    return 'his-img-green'
  }
  // 数字特殊处理（如121）
  if (!isNaN(val)) {
    return 'his-img-zise'
  }
  return 'color-default'
}
const confirmTime = (val) =>{
  cancelTime();
  const time = userTime.dateFormat(val);
  if (time) {
    dateTime.value = time;
    getRecord();
  }
}
const getWeek = (dateString) =>{
  const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
  const date = new Date(dateString.replace(/-/g, '/'));
  const year = date.getFullYear();
  const month = date.getMonth();
  const day = date.getDate();
  const weekdayIndex = new Date(year, month, day).getDay();
  return weekdays[weekdayIndex];
}
const cancelTime = () =>{
  currentDate.value = new Date();
  showTime.value = false;
}
const changePage = () =>{
  getLottery();
}
const handleCurrentChange = (val) =>{
  param.value.pageNum = val;
  getRecord();
}
const onConfirm = (item) =>{
  onCancel();
  lotItem.value = item;
  let t = localStorage.setItem('lotteryId',item.id);
  getRecord();
}
const switchType = (num) =>{
    param.value.object.status  = num;
    yxqShow.value = false;
    getRecord();
}
const onCancel = () =>{
  showLottery.value = false;
}
const count = (num) =>{
  let list =[];
  let i =num;
  for(var j=i;j>i-12;j--){
      let k='';
      if(j<=0){
          k = j+12
      }else{
          k=j
      }
      list.push(k)
  }
  for(let i=0;i<zodiac.value.length;i++){
      zodiac.value[i].sort = list[i];
  }
}
const getMarks = (st) =>{
    let srt = userTime.dateNow(st);
    let date = srt.split('-')
    let year = parseInt(date[0])
    let month = parseInt(date[1])
    let day = parseInt(date[2]);
    var today = getLunar(year,month,day);
    let str1  = "";
    zodiac.value.map(item=>{
        if(item.name==today.zodiac){
            str1 = item.id;
        }
    })
    count(str1);
}
    // 获取彩种列表
const getLottery = async() =>{
  try {
    let res = await userStore.getLotList();
    list.value = res.data;
    let t = localStorage.getItem('lotteryId');
    if(t){
      list.value.map(iten=>{
        if(iten.id==t){
          lotItem.value = iten;
        }
      })
    }else{
      lotItem.value = res.data[0];	
    }
    param.value.object.lotteryId = lotItem.value.id
    getRecord();
  } catch (error) {
     console.log('退出登录失败')
  }
}
// 获取开奖记录
const getRecord = async () => {
  // 状态检查
  if (loadStatus.value === 'loading' || loadStatus.value === 'finished') return;
  
  try {
    loadStatus.value = 'loading';
    loading.value = true;
    const currentPage = param.value.pageNum;
    
    // 设置彩票ID
    param.value.object.lotteryId = lotItem.value.id;
    
    // 发起请求
    let res = await userStore.getOpenPage(param.value);
    
    // 校验返回数据
    if (!res?.data?.list || !Array.isArray(res.data.list)) {
      console.warn('返回数据异常');
      return;
    }
    types.value = res.data.list.length > 0 ? 1 : 0
    first.value = res.data.list.length > 0 ? res.data.list[0].id :param.value.object.lotteryId 
    // 只有当前请求的页码等于预期页码时才处理数据
    if (currentPage === param.value.pageNum) {
      // 处理数据
      const processedData = processRecordData(res.data.list);
      
      // 追加数据（而不是替换）
      if (param.value.pageNum === 1) {
        // 第一页直接赋值
        tableData.value = processedData;
      } else {
        // 使用Map去重更高效
        const dataMap = new Map();
        // 先添加已有数据
        tableData.value.forEach(item => dataMap.set(item.id, item));
        // 再添加新数据（如果ID重复则覆盖）
        processedData.forEach(item => {
          if (!dataMap.has(item.id)) {
            dataMap.set(item.id, item);
          }
        });
        tableData.value = Array.from(dataMap.values());
      }
    }
    
    // 更新分页信息
    pages.value.pageSize = res.data.pageSize || param.value.pageSize;
    pages.value.total = res.data.total || 0;
    // 判断是否还有更多数据
    const hasMore = res.data.list.length >= param.value.pageSize;
    if (!hasMore) {
      finished.value = true;
      loadStatus.value = 'finished';
    } else {
      param.value.pageNum++;
      loadStatus.value = 'success';
    }
    
  } catch (error) {
    console.error('获取开奖记录失败', error);
    // 可以添加用户提示
    // showToast('加载失败，请重试');
  } finally {
    loading.value = false;
  }
};

// 提取数据处理逻辑
const processRecordData = (list) => {
  return list.map(item => {
    // 深拷贝避免修改原数据
    const newItem = { ...item };
    newItem.maks = [];
    
    if (newItem.result) {
      // 获取生肖映射
      const marks = getMarks(newItem.openTimeDay);
      
      // 处理结果
      const numlist = newItem.result.split(',');
      newItem.result = numlist;
      
      // 计算生肖
      numlist.forEach(num => {
        const sort = parseInt(num % 12) === 0 ? 12 : parseInt(num % 12);
        const zodiacItem = zodiac.value.find(item1 => item1.sort === sort);
        if (zodiacItem) {
          newItem.maks.push({
            name: zodiacItem.name,
            num: num
          });
        }
      });
    } else {
      // 未开奖的处理
      const count = (newItem.lotteryId !== 10101 && newItem.lotteryId !== 10102) ? 7 : 8;
      for (let i = 0; i < count; i++) {
        newItem.maks.push({
          name: '',
          corle: 'no',
          num: 'num'
        });
      }
    }
    
    return newItem;
  });
};

// 下拉刷新（重置数据）
const refreshRecord = async () => {
  // 重置分页参数
  param.value.pageNum = 1;
  finished.value = false;
  tableData.value = [];
  
  // 重新加载
  await getRecord();
};

// 加载更多（上拉加载）
const loadMoreRecord = async () => {
  if (loading.value || finished.value) return;
  await getRecord();
};
</script>
